import zlib, sys

POLY = 0xEDB88320
TARGET_CRC = 0xb0725dc4

# Build CRC table
table = []
for i in range(256):
    reg = i
    for _ in range(8):
        if reg & 1:
            reg = (reg >> 1) ^ POLY
        else:
            reg >>= 1
    table.append(reg)

def crc_update(reg, byte):
    return table[(reg ^ byte) & 0xFF] ^ (reg >> 8)

def crc_reverse(reg, byte):
    for _ in range(8):
        if reg & 0x80000000:
            reg = ((reg ^ POLY) << 1) | 1
        else:
            reg = (reg << 1) & 0xFFFFFFFF
    reg ^= byte
    return reg

# Verify reverse works
reg = 0xFFFFFFFF
for b in b'Hello, World! Test 123':
    reg = crc_update(reg, b)
final = reg ^ 0xFFFFFFFF
assert final == zlib.crc32(b'Hello, World! Test 123') & 0xFFFFFFFF, "Forward CRC mismatch"

reg2 = final ^ 0xFFFFFFFF
for b in reversed(b'Hello, World! Test 123'):
    reg2 = crc_reverse(reg2, b)
assert reg2 == 0xFFFFFFFF, f"Reverse CRC failed: {reg2:08x}"
print("CRC forward/reverse verified.")

# File structure: 'PASSWORD=8XDP5Q2RT9Z' + [9 unknown] + 'W54\n'
prefix = b'PASSWORD=8XDP5Q2RT9Z'
suffix = b'W54\n'

# Register after processing prefix
reg_prefix = 0xFFFFFFFF
for b in prefix:
    reg_prefix = crc_update(reg_prefix, b)

# Register needed after the 9 unknown bytes (before suffix)
reg_final = TARGET_CRC ^ 0xFFFFFFFF
reg_after_unknown = reg_final
for b in reversed(suffix):
    reg_after_unknown = crc_reverse(reg_after_unknown, b)

print(f"reg_prefix = {reg_prefix:08x}")
print(f"reg_after_unknown = {reg_after_unknown:08x}")

chars = [ord(c) for c in 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789']
print(f"Char set size: {len(chars)}")

# FORWARD: 4 bytes (36^4 = 1,679,616)
print("Computing forward states (4 bytes)...")
forward = {}
tbl = table
for a in chars:
    r1 = tbl[(reg_prefix ^ a) & 0xFF] ^ (reg_prefix >> 8)
    for b in chars:
        r2 = tbl[(r1 ^ b) & 0xFF] ^ (r1 >> 8)
        for c in chars:
            r3 = tbl[(r2 ^ c) & 0xFF] ^ (r2 >> 8)
            for d in chars:
                r4 = tbl[(r3 ^ d) & 0xFF] ^ (r3 >> 8)
                if r4 in forward:
                    forward[r4].append((a,b,c,d))
                else:
                    forward[r4] = [(a,b,c,d)]

print(f"Forward: {len(forward)} unique states")

# BACKWARD: 5 bytes (36^5 = 60,466,176)
print("Computing backward states (5 bytes)...")
found = []
target_reg = reg_after_unknown
POLY_local = POLY

for e in chars:
    r1 = target_reg
